// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    Attacker atk;

    function setUp() public { c = new W_WALLET(address(new Log())); atk = new Attacker(); atk.setC(c); }

    function testFuzz_property(uint256 deposit, uint256 reDeposit, uint256 withdraw) public {
        deposit = bound(deposit, 1 ether, 1000 ether);
        withdraw = bound(withdraw, 1, deposit);
        reDeposit = bound(reDeposit, 1, 1000 ether);

        vm.deal(address(atk), deposit + reDeposit + 1 ether);

        // initial Put (not locked, succeeds in both versions)
        atk.put(deposit);

        // advance time so Collect's time check passes
        vm.warp(block.timestamp + 1);

        // Collect triggers re-entrant Put of reDeposit inside the external call
        atk.attack(withdraw, reDeposit);

        // General rule: after Collect, recorded balance is exactly prior balance minus withdrawn amount.
        (, uint256 bal) = c.Acc(address(atk));
        assertTrue(bal == deposit - withdraw);
    }
}

contract Attacker {
    W_WALLET c;
    uint256 public armedAmt;

    function setC(W_WALLET _c) external { c = _c; }

    function put(uint256 amount) external {
        c.Put{value: amount}(0);
    }

    function attack(uint256 withdraw, uint256 reDep) external {
        armedAmt = reDep;
        c.Collect(withdraw);
    }

    receive() external payable {
        try c.Put{value: armedAmt}(0) {} catch {}
    }
}
